package mrpapermoon.whisper.contacts.utilsimport mrpapermoon.whisper.contacts.db.ContactEntityimport mrpapermoon.whisper.entity.WhispererColorimport mrpapermoon.whisper.entity.WhispererIconobject UserGenerator {	fun createRandomContact(whispererId: String, name: String): ContactEntity {		return ContactEntity(			whispererId = whispererId,			name = name,			color = WhispererColor.entries.random(),			icon = WhispererIcon.entries.random(),		)	}}